async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "digital-marketing" },
    update: { name: "Digital Marketing" },
    create: {
      group: "Marketing", name: "Digital Marketing", slug: "digital-marketing" },
  });

  const subcategoryMap: Record<string, string> = {
    "seo-content-marketing": "SEO & Content Marketing",
    "paid-advertising-campaigns": "Paid Advertising & Campaigns",
    "digital-marketing-strategy-channels": "Digital Marketing Strategy & Channels",
    "analytics-measurement-cro": "Analytics, Measurement & CRO",
    "digital-marketing-fundamentals": "Digital Marketing Fundamentals",
  };

  const subcategoryIds: Record<string, string> = {};
  for (const [slug, name] of Object.entries(subcategoryMap)) {
    const sub = await prisma.subcategory.upsert({
      where: { categoryId_slug: { categoryId: category.id, slug } },
      update: { name, categoryId: category.id },
      create: { name, slug, categoryId: category.id },
    });
    subcategoryIds[slug] = sub.id;
  }

  for (const item of questions) {
    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId: subcategoryIds[item.subcategorySlug],
        experienceLevel: item.experienceLevel,
        difficulty: item.difficulty,
        interviewType: item.interviewType,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId: subcategoryIds[item.subcategorySlug],
        experienceLevel: item.experienceLevel,
        difficulty: item.difficulty,
        interviewType: item.interviewType,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
    });
  }

  console.log(`Digital Marketing interview seed completed: ${questions.length} questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
